diff --git a/ops/experiment_sandbox/async_windows.go b/ops/experiment_sandbox/async_windows.go
index b5eb15d..98b354b 100644
--- a/ops/experiment_sandbox/async_windows.go
+++ b/ops/experiment_sandbox/async_windows.go
@@ -39,21 +39,22 @@ type StartOptions struct {
 }

 type Process struct {
-	mu      sync.Mutex
-	writeMu sync.Mutex
-	stdin   *os.File
-	cancel  context.CancelFunc
-	done    chan struct{}
-	ready   chan error
-	receipt Receipt
-	err     error
+	mu        sync.Mutex
+	writeGate chan struct{}
+	stopped   <-chan struct{}
+	stdin     *os.File
+	cancel    context.CancelFunc
+	done      chan struct{}
+	ready     chan error
+	receipt   Receipt
+	err       error
 }

 // Start returns after suspended identity persistence and ResumeThread succeed.
 // It owns process termination, stream draining and staging cleanup until Wait.
 func Start(ctx context.Context, c Command, options StartOptions) (*Process, error) {
 	child, cancel := context.WithCancel(ctx)
-	p := &Process{cancel: cancel, done: make(chan struct{}), ready: make(chan error, 1)}
+	p := &Process{cancel: cancel, done: make(chan struct{}), ready: make(chan error, 1), writeGate: make(chan struct{}, 1), stopped: child.Done()}
 	go func() {
 		r, err := runSandbox(child, c, options, p)
 		p.mu.Lock()
@@ -87,16 +88,36 @@ func (p *Process) Write(ctx context.Context, frame []byte) error {
 	if len(frame) == 0 || len(frame) > 64*1024 {
 		return errors.New("bounded protocol frame required")
 	}
-	p.writeMu.Lock()
-	defer p.writeMu.Unlock()
+	bounded, cancel := context.WithTimeout(ctx, 5*time.Second)
+	defer cancel()
+	if err := bounded.Err(); err != nil {
+		return err
+	}
+	select {
+	case p.writeGate <- struct{}{}:
+	case <-bounded.Done():
+		return bounded.Err()
+	case <-p.stopped:
+		return errors.New("process input closed")
+	case <-p.done:
+		return errors.New("process completed")
+	}
+	defer func() { <-p.writeGate }()
+	if err := bounded.Err(); err != nil {
+		return err
+	}
+	select {
+	case <-p.stopped:
+		return errors.New("process input closed")
+	default:
+	}
+	frame = append([]byte(nil), frame...)
 	p.mu.Lock()
 	f := p.stdin
 	p.mu.Unlock()
 	if f == nil {
 		return errors.New("process input closed")
 	}
-	bounded, cancel := context.WithTimeout(ctx, 5*time.Second)
-	defer cancel()
 	// Windows anonymous pipes are synchronous and reject SetWriteDeadline.
 	// On timeout cancel the Job, which closes the child's read handle and
 	// releases this one pending write; never continue the protocol afterwards.
@@ -114,6 +135,8 @@ func (p *Process) Write(ctx context.Context, frame []byte) error {
 	case <-bounded.Done():
 		p.cancel()
 		return bounded.Err()
+	case <-p.stopped:
+		return errors.New("process input closed")
 	}
 }

diff --git a/ops/experiment_sandbox/async_windows_test.go b/ops/experiment_sandbox/async_windows_test.go
index 97b3109..987720f 100644
--- a/ops/experiment_sandbox/async_windows_test.go
+++ b/ops/experiment_sandbox/async_windows_test.go
@@ -4,6 +4,7 @@ package sandbox

 import (
 	"bufio"
+	"bytes"
 	"context"
 	"encoding/json"
 	"errors"
@@ -155,3 +156,45 @@ func TestRuntimeSandboxStreamLimit(t *testing.T) {
 	}
 	t.Logf("RUNTIME_STREAM_LIMIT bytes=%d stopped=%v drained=%v error=%v", len(r.Stdout), r.Stopped, r.StreamsDrained, err)
 }
+
+func TestRuntimeSandboxQueuedWriteDeadline(t *testing.T) {
+	p, err := Start(context.Background(), runtimeSandboxCommand(t, "wait"), StartOptions{Interactive: true})
+	if err != nil {
+		t.Fatal(err)
+	}
+	first := make(chan error, 1)
+	go func() { first <- p.Write(context.Background(), bytes.Repeat([]byte("x"), 64*1024)) }()
+	deadline := time.Now().Add(time.Second)
+	for len(p.writeGate) == 0 {
+		if time.Now().After(deadline) {
+			p.Cancel()
+			t.Fatal("first writer did not acquire gate")
+		}
+		time.Sleep(time.Millisecond)
+	}
+	ctx, cancel := context.WithTimeout(context.Background(), 40*time.Millisecond)
+	defer cancel()
+	start := time.Now()
+	err = p.Write(ctx, []byte("queued\n"))
+	elapsed := time.Since(start)
+	if !errors.Is(err, context.DeadlineExceeded) || elapsed > 200*time.Millisecond {
+		p.Cancel()
+		t.Fatalf("queued deadline: %v %s", err, elapsed)
+	}
+	select {
+	case <-p.stopped:
+		t.Fatal("queued caller cancellation stopped active writer")
+	default:
+	}
+	p.Cancel()
+	select {
+	case <-first:
+	case <-time.After(time.Second):
+		t.Fatal("blocked first writer did not stop")
+	}
+	r, err := p.Wait(context.Background())
+	if err != nil || !r.Stopped || !r.CleanupComplete {
+		t.Fatalf("cancel cleanup: %+v %v", r, err)
+	}
+	t.Logf("RUNTIME_QUEUED_WRITE deadline_ms=40 elapsed_ms=%d stopped=%v", elapsed.Milliseconds(), r.Stopped)
+}
